-- CF Toronto Eaton Centre, rebuilt from its leasing plans (Phase 3: the shell).
--
-- The geometry comes from Data/*.lua, generated by tools/eaton/extract.py and
-- tools/eaton/to_lua.py from the real plans. Everything there is in plan feet:
--   u = feet north of the Queen St wall, v = feet west of the Yonge St wall.
-- TorontoLayout.EATON_SCALE sets the horizontal scale. LEVEL_Y sets the floor elevations.
--
-- Built: the concourse (Urban Eatery) and Levels 1-3 with the real floor
-- openings, exterior walls with the street entrances, unit walls and storefront
-- headers on their traced lines, glass balustrades round the openings, the
-- columns that stand in public space, the glass barrel vault over the galleria,
-- the roof, working escalators (Data/Circulation.lua) and lifts, and the opening
-- for the passage to Dundas station (built by Transit).
-- Later phases: storefronts, finishes, signage, interiors.
local CollectionService = game:GetService("CollectionService")
local HttpService = game:GetService("HttpService")
local ReplicatedStorage = game:GetService("ReplicatedStorage")

local Util = require(script.Parent.Util)
local Kit = require(script.Parent.StationKit)
local Workplaces = require(script.Parent.Workplaces)
local TorontoLayout = require(script.Parent.TorontoLayout)
local Exterior = require(script.Exterior)
local Galleria = require(script.Galleria)
local Stores = require(script.Stores)

local DATA = script.Data
local LEVEL_DATA = {
	{ idx = 0, key = "concourse", name = "Level_Concourse", label = "Concourse", data = require(DATA.concourse) },
	{ idx = 1, key = "L1", name = "Level_01", label = "Level 1", data = require(DATA.L1) },
	{ idx = 2, key = "L2", name = "Level_02", label = "Level 2", data = require(DATA.L2) },
	{ idx = 3, key = "L3", name = "Level_03", label = "Level 3", data = require(DATA.L3) },
	{ idx = 4, key = "L4", name = "Level_04", label = "Level 4", data = require(DATA.L4) },
}
local BY_IDX = {}
for _, L in ipairs(LEVEL_DATA) do
	BY_IDX[L.idx] = L
end
local SHARED = require(DATA.Shared)

-- Tenants (made-up names; tools/eaton/tenants.py): "<level>:<unit>" -> record.
local TENANTS = {}
for _, t in ipairs(require(ReplicatedStorage.Shared.Catalog.EatonTenants)) do
	TENANTS[t.level .. ":" .. t.unit] = t
end

-- Sign-band colours by category (the store name is white on the band).
local CATEGORY_COLOUR = {
	fashion = Color3.fromRGB(28, 28, 32),
	footwear = Color3.fromRGB(96, 40, 30),
	sports = Color3.fromRGB(20, 60, 120),
	electronics = Color3.fromRGB(30, 34, 44),
	beauty = Color3.fromRGB(150, 60, 100),
	jewellery = Color3.fromRGB(120, 96, 40),
	food = Color3.fromRGB(170, 50, 30),
	cafe = Color3.fromRGB(90, 56, 36),
	optical = Color3.fromRGB(30, 90, 100),
	pharmacy = Color3.fromRGB(180, 30, 40),
	books = Color3.fromRGB(40, 100, 60),
	department = Color3.fromRGB(16, 16, 20),
	services = Color3.fromRGB(60, 64, 72),
}

local EatonCentre = {}
EatonCentre.safeZones = {} -- underground spaces players may stand in (the concourse)

local S = require(script.Parent.TorontoLayout).EATON_SCALE -- studs per plan foot (1: true scale)
local SLAB = 1
local HEADER = 13 -- storefront header starts this high above the floor
-- Floor heights by level. Street level is Level 3 at Yonge & Dundas (the plans
-- put the TTC entrance on Level 2 and the transit/PATH links on Level 1; the
-- mall's own map shows the Yonge & Dundas entrance on Level 3). Level 2 sits on
-- the subway passages' level (-17). Our streets are flat; the real Yonge St
-- rises toward Dundas, so at the Queen end the real street meets a lower level.
local LEVEL_Y = { [0] = -54.75, [1] = -37, [2] = -17, [3] = Util.WALK_TOP, [4] = Util.WALK_TOP + 20, [5] = Util.WALK_TOP + 40 }
local CONCOURSE_Y = LEVEL_Y[0]
local ESC_W = 5 -- one escalator's width (studs)
local ESC_SPEED = 7
-- Centre of the round feature opposite A015 on the registered Level 1 sheet.
local FOUNTAIN_U, FOUNTAIN_V = 468.25, 162.75
local COURT_RADIUS = 13.25 -- outer circle on the plan, in feet

local function overlapsFountain(u, v, radius)
	return (u - FOUNTAIN_U)^2 + (v - FOUNTAIN_V)^2 < (COURT_RADIUS + radius)^2
end

-- Is plan point (u, v) on a floor plate of level idx?
local function onSlab(idx, u, v)
	for _, r in ipairs(BY_IDX[idx].data.slabs) do
		if u >= r[1] and u <= r[3] and v >= r[2] and v <= r[4] then
			return true
		end
	end
	return false
end

-- Dig out the concourse before the ground is built (called from Toronto.layout).
function EatonCentre.layout(rect)
	local minU, maxU, minV, maxV = math.huge, -math.huge, math.huge, -math.huge
	for _, r in ipairs(BY_IDX[0].data.slabs) do
		minU, maxU = math.min(minU, r[1]), math.max(maxU, r[3])
		minV, maxV = math.min(minV, r[2]), math.max(maxV, r[4])
	end
	local x0, x1 = rect.maxX - maxV * S, rect.maxX - math.max(0, minV) * S
	local z0, z1 = rect.maxZ - maxU * S, rect.maxZ - minU * S
	if SHARED.dig then
		local d = SHARED.dig
		x0, x1 = rect.maxX - d[4] * S, rect.maxX - d[2] * S
		z0, z1 = rect.maxZ - d[3] * S, rect.maxZ - d[1] * S
	end
	local min = Vector3.new(x0 - 1, CONCOURSE_Y - 1.5, z0 - 1)
	local max = Vector3.new(x1, 0.2, z1 + 1)
	Util.carve(min, max)
	table.insert(EatonCentre.safeZones, { min = min - Vector3.new(2, 2, 2), max = max + Vector3.new(2, 6, 2) })
end


local V3 = Vector3.new
local M = Enum.Material
local C = Color3.fromRGB

local FLOOR = C(210, 203, 192) -- warm light-grey limestone (photos), beside the darker court inlays
local PLASTER = C(204, 196, 184) -- warm greige panels (not clinical white)
local FASCIA = C(216, 208, 196) -- storefront bulkheads, warm stone
local FACADE = C(168, 160, 150)
local FACADE_DARK = C(92, 96, 104)
local STEEL = C(196, 198, 202)
local GLASS = C(196, 222, 232)
local CEILING = C(222, 214, 202) -- warm, so the soffits don't read clinical
local DOOR_W = 7 -- the opening in a shop's glass front (studs)

-- Finishes on the traced public frontages. Keep the catalog name on the sign.
local COURT_FRONTS = {
	["Zara"] = {
		panel = C(235, 221, 202), ink = C(40, 34, 31), trim = C(80, 68, 58),
		font = Enum.Font.Bodoni, lettering = 0.38, bay = 12,
	},
	["Indigo Books Music More"] = {
		panel = C(166, 114, 65), ink = C(252, 244, 224), trim = C(89, 64, 48),
		font = Enum.Font.Garamond, lettering = 0.62, bay = 18,
	},
}

-- A store name on one face of a header, on a coloured band at its foot.
local function storeSign(part, face, name, colour, bandH, finish)
	local gui = Instance.new("SurfaceGui")
	gui.Face = face
	gui.SizingMode = Enum.SurfaceGuiSizingMode.PixelsPerStud
	gui.PixelsPerStud = 24
	gui.LightInfluence = 0
	local band = Instance.new("Frame")
	band.AnchorPoint = Vector2.new(0, 1)
	band.Position = UDim2.fromScale(0, 1)
	band.Size = UDim2.new(1, 0, 0, bandH * 24)
	band.BackgroundTransparency = 1
	band.BorderSizePixel = 0
	band.Parent = gui
	local label = Instance.new("TextLabel")
	label.BackgroundTransparency = 1
	label.AnchorPoint = Vector2.new(0.5, 0.5)
	label.Position = UDim2.fromScale(0.5, 0.5)
	label.Size = UDim2.fromScale(finish and finish.lettering or 0.7, 0.62)
	label.Font = finish and finish.font or Enum.Font.GothamBold
	label.TextScaled = true
	label.TextColor3 = colour
	label.TextStrokeTransparency = 0.85
	label.Text = finish and name or string.upper(name)
	label.Parent = band
	gui.Parent = part
	return gui
end

local function folderIn(parent, name)
	local f = Instance.new("Folder")
	f.Name = name
	f.Parent = parent
	return f
end

-- Build. rect = T.EATON; the Yonge St wall is rect.maxX, the Queen St wall rect.maxZ.
function EatonCentre.build(root, rect)
	local yongeX, queenZ = rect.maxX, rect.maxZ
	local base = Util.WALK_TOP

	local function P(u, v, y)
		return V3(yongeX - v * S, y, queenZ - u * S)
	end

	local function levelY(i)
		return LEVEL_Y[i]
	end
	local roofY = levelY(4) -- Level 3's roof (Level 4's floor where it exists)
	local roof4Y = levelY(5) -- Level 4's roof

	-- A flat rectangle in plan feet, top at y.
	local function plate(parent, r, y, thick, colour, material, collide)
		local u0, v0, u1, v1 = r[1], r[2], r[3], r[4]
		local size = V3((v1 - v0) * S, thick, (u1 - u0) * S)
		local cf = CFrame.new(P((u0 + u1) / 2, (v0 + v1) / 2, y - thick / 2))
		if collide == false then
			return Util.deco(parent, size, cf, colour, material)
		end
		return Util.solid(parent, size, cf, colour, material)
	end

	-- A vertical panel along a plan segment, from y up by height.
	local function panel(parent, a, b, y, height, thick, colour, material, collide)
		local pa, pb = P(a[1], a[2], 0), P(b[1], b[2], 0)
		local length = (pb - pa).Magnitude
		if length < 0.2 then
			return nil
		end
		local mid = (pa + pb) / 2 + V3(0, y + height / 2, 0)
		local cf = CFrame.lookAt(mid, mid + (pb - pa))
		local size = V3(thick, height, length + thick * 0.5)
		if collide == false then
			return Util.deco(parent, size, cf, colour, material)
		end
		return Util.solid(parent, size, cf, colour, material)
	end

	-- Split a Level 1 wall a->b around Exterior.DOORS: returns pieces
	-- { a, b, from } where from is the height the piece starts at (0 = the
	-- floor; a door's height = the lintel over it; nil = left out).
	local function doorPieces(a, b, level)
		if level ~= 1 then
			return { { a, b, 0 } }
		end
		local cuts = {}
		for _, d in ipairs(Exterior.DOORS) do
			-- Liang-Barsky: the part of a->b inside the door's box.
			local t0, t1 = 0, 1
			local du, dv = b[1] - a[1], b[2] - a[2]
			local ok = true
			for _, e in ipairs({ { -du, a[1] - d.u0 }, { du, d.u1 - a[1] }, { -dv, a[2] - d.v0 }, { dv, d.v1 - a[2] } }) do
				local pp, q = e[1], e[2]
				if math.abs(pp) < 1e-9 then
					if q < 0 then
						ok = false
					end
				else
					local r = q / pp
					if pp < 0 then
						t0 = math.max(t0, r)
					else
						t1 = math.min(t1, r)
					end
				end
			end
			if ok and t1 - t0 > 0.01 then
				table.insert(cuts, { t0, t1, d.h })
			end
		end
		if #cuts == 0 then
			return { { a, b, 0 } }
		end
		table.sort(cuts, function(x, y)
			return x[1] < y[1]
		end)
		local function at(t)
			return { a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t }
		end
		local out, t = {}, 0
		for _, c in ipairs(cuts) do
			if c[1] > t then
				table.insert(out, { at(t), at(c[1]), 0 })
			end
			if c[3] then
				table.insert(out, { at(c[1]), at(c[2]), c[3] })
			end
			t = math.max(t, c[2])
		end
		if t < 1 then
			table.insert(out, { at(t), b, 0 })
		end
		return out
	end

	local mall = folderIn(root, "EatonCentre")
	local levels = {}
	-- Galleria finishes (Galleria.lua): balcony bands, floor stripes, downlights.
	local gctx = { P = P, S = S, onSlab = onSlab, lights = { n = 0, max = 110 } }

	---------------------------------------------------------------------------
	-- Escalators: placed by tools/eaton/to_lua.py from Data/Circulation.lua (top
	-- end at the drawn end that leads on to the upper corridor; the upper floor is
	-- already cut open over each one, with balustrades along the cut).
	---------------------------------------------------------------------------
	local escPlans = {}
	for _, e in ipairs(SHARED.escalators) do
		local top, bottom = e.top, e.bottom
		-- The Yonge & Dundas entrance hall's escalator (Level 2 up to the street):
		-- turned round so you step off at its west end, into the hall, rather
		-- than facing the wall of the store in the corner.
		if e.from == 2 and e.to == 3 and math.abs(top[1] - 1332.8) < 1 and math.abs(top[2] - 42.3) < 1 then
			top, bottom = e.bottom, e.top
		end
		table.insert(escPlans, { bank = e, top = top, bottom = bottom, dTop = 0, dBottom = 0 })
	end
	-- Sorrel Studio (unit B212) is three storeys, street Level 3 down to Level 1,
	-- with its own pair of escalators side by side in a well through its floors
	-- (Stores.WELLS cuts the floors; balustrades round the cuts below).
	for _, e in ipairs(Stores.STORE_ESCALATORS) do
		table.insert(escPlans, { bank = e, top = e.top, bottom = e.bottom, dTop = 0, dBottom = 0, store = true })
	end
	for _, e in ipairs(Stores.MALL_ESCALATORS) do
		table.insert(escPlans, { bank = e, top = e.top, bottom = e.bottom, dTop = 0, dBottom = 0 })
	end
	for _, e in ipairs(Exterior.escalators()) do
		table.insert(escPlans, { bank = e, top = e.top, bottom = e.bottom, dTop = 0, dBottom = 0 })
	end
	-- The plan's own railings that now stand inside one of the added wells go.
	local function railCut(i, a, b)
		return Stores.inWell(i, a[1], a[2], 0.6) and Stores.inWell(i, b[1], b[2], 0.6)
	end
	-- The opening in the concourse wall for the passage to the subway (Transit).
	local link = TorontoLayout.EATON_LINK


	---------------------------------------------------------------------------
	-- Floors, walls, storefront headers, balustrades.
	---------------------------------------------------------------------------
	for _, L in ipairs(LEVEL_DATA) do
		local i = L.idx
		local y = levelY(i)
		local f = folderIn(mall, L.name)
		local arch = folderIn(f, "Architecture")
		local retail = folderIn(f, "Retail")
		local atrium = folderIn(f, "Atrium")
		levels[i] = { folder = f, y = y }

		local slabs = {}
		for _, r0 in ipairs(L.data.slabs) do
			for _, r in ipairs(Exterior.clipSlab(r0, i)) do
				table.insert(slabs, r)
			end
		end
		for _, r in ipairs(Exterior.fill(i, L.data.slabs)) do
			table.insert(slabs, r)
		end
		slabs = Stores.clipWells(slabs, i)
		for _, r in ipairs(slabs) do
			local p = plate(arch, r, y, SLAB, FLOOR, M.CeramicTiles)
			p.Reflectance = 0.08
			p.Name = "Floor"
			Stores.skin(p, "mall_floor_tile", 16, FLOOR)
			-- A plain ceiling under the floors above people's heads (Levels 2-3, and
			-- Level 1 where the concourse is below).
			if i >= 2 or (i == 1 and onSlab(0, (r[1] + r[3]) / 2, (r[2] + r[4]) / 2)) then
				local c = plate(arch, r, y - SLAB - 0.02, 0.2, CEILING, M.SmoothPlastic, false)
				c.Name = "Ceiling"
				c.CastShadow = false
			end
		end

		-- The sign goes on each shop's longest storefront edge on this level.
		local signEdge = {}
		for k, w in ipairs(L.data.walls) do
			if w[5] == 2 and w[6] then
				local len = math.sqrt((w[3] - w[1]) ^ 2 + (w[4] - w[2]) ^ 2)
				local best = signEdge[w[6]]
				if not best or len > best.len then
					signEdge[w[6]] = { k = k, len = len }
				end
			end
		end

		local top = (i >= 3) and (levelY(i + 1) - y) or (levelY(i + 1) - SLAB - y)
		-- The hallway kiosks (plan units Z...): the plan draws them as little
		-- rooms, walls to the ceiling; they're built as low open kiosks instead
		-- (Galleria.kiosk), so their walls are left out here.
		local kiosks = {}
		for _, u in ipairs(L.data.units or {}) do
			if string.sub(u.unit, 1, 1) == "Z" and u.umin then
				table.insert(kiosks, u)
			end
		end
		local function inKiosk(p)
			for _, u in ipairs(kiosks) do
				if p[1] >= u.umin - 0.6 and p[1] <= u.umax + 0.6 and p[2] >= u.vmin - 0.6 and p[2] <= u.vmax + 0.6 then
					return true
				end
			end
			return false
		end
		for _, u in ipairs(kiosks) do
			local t = TENANTS[i .. ":" .. u.unit]
			if t and t.status == "open" then
				local ok, err = pcall(Galleria.kiosk, retail, P, y, u, t, Stores.design(t))
				if not ok then
					warn("[EatonCentre] kiosk " .. u.unit .. ": " .. tostring(err))
				end
			end
		end
		for wi, w in ipairs(L.data.walls) do
			local a, b, kind = { w[1], w[2] }, { w[3], w[4] }, w[5]
			if (w[6] and string.sub(w[6], 1, 1) == "Z") or (#kiosks > 0 and inKiosk(a) and inKiosk(b)) then
				continue
			end
			local mode = i >= 1 and Exterior.wallMode(kind, a, b, i) or nil
			-- The anchor's front on to the old corner hall: at street level the
			-- whole corner is the store now (Corner.lua), so its floor runs on.
			if i == 3 and math.min(a[1], b[1]) >= 1336 and math.max(a[1], b[1]) <= 1389 and math.min(a[2], b[2]) >= 53 and math.max(a[2], b[2]) <= 58 then
				continue
			end
			if mode == "skip" then
				continue
			elseif mode == "rail" then
				-- The drum's curved edge on Level 3: a glass balustrade looking out.
				local g = panel(atrium, a, b, y, 3.6, 0.25, GLASS, M.Glass)
				if g then
					g.Transparency = 0.55
					g.CastShadow = false
					g.Name = "Balustrade"
				end
				panel(atrium, a, b, y + 3.6, 0.3, 0.45, STEEL, M.Metal)
				continue
			elseif mode == "window" then
				-- A shop window to the street, wall above it.
				local g = panel(arch, a, b, y, 13, 0.4, C(200, 214, 222), M.Glass)
				if g then
					g.Transparency = 0.45
					g.CastShadow = false
					g.Name = "StreetWindow"
				end
				panel(arch, a, b, y + 13, top - 13, 1.2, FACADE, M.Concrete)
				continue
			elseif mode == "glass" then
				local g = panel(arch, a, b, y, top, 0.4, C(150, 180, 205), M.Glass)
				if g then
					g.Transparency = 0.35
					g.Reflectance = 0.25
					g.CastShadow = false
					g.Name = "AtriumGlass"
				end
				continue
			elseif mode == "door" then
				kind = 4
			end
			local closed = mode == "closed"
			if kind == 1 then
				for _, pc in ipairs(doorPieces(a, b, i)) do
					panel(retail, pc[1], pc[2], y + pc[3], top - pc[3], 0.5, PLASTER, M.SmoothPlastic)
				end
			elseif kind == 2 then
				local tenant = w[6] and TENANTS[i .. ":" .. w[6]]
				local len = math.sqrt((b[1] - a[1]) ^ 2 + (b[2] - a[2]) ^ 2) * S
				local isSign = w[6] and signEdge[w[6]] and signEdge[w[6]].k == wi
				-- Which face of a panel along a->b looks out to the corridor.
				local function outFace(part)
					local out = V3(-(w[8] or 0), 0, -(w[7] or 0))
					return part.CFrame.RightVector:Dot(out) > 0 and Enum.NormalId.Right or Enum.NormalId.Left
				end
				if not tenant or tenant.status == "back" then
					panel(retail, a, b, y, top, 0.5, PLASTER, M.SmoothPlastic)
				elseif tenant.status == "vacant" then
					-- Hoarding across the front while the unit is empty.
					local h = panel(retail, a, b, y, top, 0.5, C(232, 230, 224), M.SmoothPlastic)
					if h and isSign and len >= 8 then
						h.Name = "Hoarding"
						storeSign(h, outFace(h), "Coming soon", C(70, 74, 84), 3)
					end
				else
					-- Header with the store's sign band, glass front with a doorway.
					local finish = COURT_FRONTS[tenant.real]
					local colour = finish and finish.ink or CATEGORY_COLOUR[tenant.category] or FASCIA
					local h = panel(retail, a, b, y + HEADER, top - HEADER, 0.6, finish and finish.panel or FASCIA, M.SmoothPlastic)
					-- Every other front is dressed by Stores.storefront (piers, sign band
					-- with lettering, blade sign, mullions, plinths); the big anchors by
					-- the Yonge & Dundas entrance get Galleria.anchorFronts instead.
					local dressed = false
					local real = string.lower(tenant.real or "")
					if not finish and real ~= "uniqlo" and real ~= "simons" and real ~= "h m" and real ~= "h & m" then
						local out = V3(-(w[8] or 0), 0, -(w[7] or 0))
						if out.Magnitude > 0.5 then
							local design = Stores.design(tenant)
							-- the Urban Eatery's counters on the concourse get its own look
							if i == 0 and (tenant.category == "food" or tenant.category == "cafe") then
								design.eatery = true
							end
							local okF, res = pcall(Stores.storefront, retail, P(a[1], a[2], y), P(b[1], b[2], y), out.Unit, y, top, HEADER, design, tenant.name, isSign and len >= 5, len >= 12 and tenant.category ~= "department")
							dressed = okF and res
						end
					end
					if h then
						h.Name = "Storefront"
						h:SetAttribute("Unit", tenant.unit)
						h:SetAttribute("Store", tenant.name)
						if finish and len >= 5 then
							-- Narrow joints and sill on the header itself leave the entry below clear.
							local face = outFace(h)
							local side = face == Enum.NormalId.Right and 1 or -1
							local surface = h.CFrame * CFrame.new(side * (h.Size.X / 2 + 0.04), 0, 0)
							Util.deco(retail, V3(0.08, 0.18, len), surface * CFrame.new(0, -h.Size.Y / 2 + 0.09, 0), finish.trim, M.Metal)
							local bays = math.max(1, math.floor(len / finish.bay + 0.5))
							for j = 1, bays - 1 do
								local z = len * (j / bays - 0.5)
								-- Keep the sign on an uninterrupted centre panel.
								if not isSign or math.abs(z) > len * finish.lettering / 2 then
									Util.deco(retail, V3(0.08, h.Size.Y, 0.12), surface * CFrame.new(0, 0, z), finish.trim, M.Metal)
								end
							end
						end
						if isSign and len >= 5 and not dressed then
							storeSign(h, outFace(h), tenant.name, colour, 3.5, finish)
						end
					end
					-- Anchors (department stores) open straight on to the mall, as the real
					-- ones do: you walk through them from one wing to the next.
					-- Mall shops open across most of their front (as the real ones do,
					-- behind roll-down grilles), with display glass either side; small
					-- units are open full width.
					if len >= 12 and tenant.category ~= "department" then
						local opening = math.clamp(len * 0.6, DOOR_W, len - 4)
						local doorT = opening / 2 / len
						for _, seg in ipairs({ { 0, 0.5 - doorT }, { 0.5 + doorT, 1 } }) do
							local pa = { a[1] + (b[1] - a[1]) * seg[1], a[2] + (b[2] - a[2]) * seg[1] }
							local pb = { a[1] + (b[1] - a[1]) * seg[2], a[2] + (b[2] - a[2]) * seg[2] }
							local g = panel(retail, pa, pb, y, HEADER, 0.3, GLASS, M.Glass)
							if g then
								g.Transparency = 0.65
								g.CastShadow = false
								g.Name = "ShopWindow"
							end
						end
					end
				end
			elseif kind == 3 then
				for _, pc in ipairs(doorPieces(a, b, i)) do
					local h = top + ((i == 3) and 3 or 0) - pc[3]
					local len = math.sqrt((pc[2][1] - pc[1][1]) ^ 2 + (pc[2][2] - pc[1][2]) ^ 2) * S
					if i == 3 and pc[3] == 0 and len >= 6 then
						-- Street level: display windows between piers, a dark band over
						-- them, the facade above.
						local bays = math.max(1, math.floor(len / 10 + 0.5))
						for k = 0, bays - 1 do
							local t0, t1 = k / bays, (k + 1) / bays
							local pa = { pc[1][1] + (pc[2][1] - pc[1][1]) * t0, pc[1][2] + (pc[2][2] - pc[1][2]) * t0 }
							local pb = { pc[1][1] + (pc[2][1] - pc[1][1]) * t1, pc[1][2] + (pc[2][2] - pc[1][2]) * t1 }
							local g = panel(arch, pa, pb, y, 12, 0.6, C(214, 222, 226), M.Glass)
							if g then
								g.Transparency = 0.35
								g.Reflectance = 0.15
								g.CastShadow = false
								g.Name = "StreetWindow"
							end
							local post = P(pa[1], pa[2], y + 6)
							Util.deco(arch, V3(1.6, 12, 1.6), CFrame.new(post), FACADE, M.Concrete)
						end
						panel(arch, pc[1], pc[2], y + 12, 2, 1.4, FACADE_DARK, M.Metal)
						-- A slim canopy over the windows, out over the sidewalk.
						do
							local du, dv = pc[2][1] - pc[1][1], pc[2][2] - pc[1][2]
							local L2 = math.sqrt(du * du + dv * dv)
							local nu, nv = -dv / L2, du / L2
							local mu, mv = (pc[1][1] + pc[2][1]) / 2, (pc[1][2] + pc[2][2]) / 2
							if onSlab(3, mu + nu * 3, mv + nv * 3) then
								nu, nv = -nu, -nv -- the floor is that way: out is the other
							end
							local c0, c1 = P(mu, mv, y + 14.3), P(mu + nu * 3, mv + nv * 3, y + 14.3)
							local cf = CFrame.lookAt((c0 + c1) / 2, (c0 + c1) / 2 + (c1 - c0))
							Util.deco(arch, V3(len, 0.5, 3), cf, FACADE_DARK, M.Metal).CastShadow = false
						end
						local wall = panel(arch, pc[1], pc[2], y + 14, h - 14, 1.2, FACADE, M.Concrete)
						if wall then
							wall.Name = "ExteriorWall"
						end
					else
						local wall = panel(arch, pc[1], pc[2], y + pc[3], h, 1.2, FACADE, M.Concrete)
						if wall then
							wall.Name = "ExteriorWall"
							if i == 4 and len >= 6 then
								-- A ribbon of windows along the upper floor.
								local band = panel(arch, pc[1], pc[2], y + 6, 6, 1.5, C(70, 86, 100), M.Glass, false)
								if band then
									band.Reflectance = 0.3
									band.CastShadow = false
								end
							end
						end
					end
				end
			elseif kind == 4 then
				-- Street entrance: a bank of glass doors (the leaves don't block you),
				-- dark frames between them, a dark lintel and glass above.
				local len = math.sqrt((b[1] - a[1]) ^ 2 + (b[2] - a[2]) ^ 2) * S
				local nDoors = math.max(1, math.floor(len / 6 + 0.5))
				for k = 0, nDoors - 1 do
					local t0, t1 = k / nDoors, (k + 1) / nDoors
					local pa = { a[1] + (b[1] - a[1]) * t0, a[2] + (b[2] - a[2]) * t0 }
					local pb = { a[1] + (b[1] - a[1]) * t1, a[2] + (b[2] - a[2]) * t1 }
					local leaf = panel(arch, pa, pb, y, 12, 0.2, C(190, 214, 226), M.Glass, closed)
					if leaf then
						leaf.Transparency = 0.7
						leaf.CastShadow = false
						leaf.Name = "Door"
					end
					local post = P(pa[1], pa[2], y + 6)
					Util.deco(arch, V3(0.5, 12, 0.5), CFrame.new(post), FACADE_DARK, M.Metal)
				end
				panel(arch, a, b, y + 12, 1.5, 1.4, FACADE_DARK, M.Metal)
				local t = panel(arch, a, b, y + 13.5, top - 13.5, 0.4, GLASS, M.Glass, false)
				if t then
					t.Transparency = 0.45
					t.Name = "EntranceGlass"
				end
			end
		end

		-- Glass balustrades with a steel handrail round every floor opening (and
		-- round the store's escalator wells, and across the old top of the
		-- entrance hall's escalator now it runs the other way).
		local extraRails = Stores.wellRails(i)
		if i == 3 then
			table.insert(extraRails, { 1326, 40, 1335, 48.5 })
		end
		for _, r in ipairs(extraRails) do
			local g = panel(atrium, { r[1], r[2] }, { r[3], r[4] }, y, 3.6, 0.25, GLASS, M.Glass)
			if g then
				g.Transparency = 0.55
				g.CastShadow = false
				g.Name = "Balustrade"
			end
			panel(atrium, { r[1], r[2] }, { r[3], r[4] }, y + 3.6, 0.3, 0.45, STEEL, M.Metal)
			panel(atrium, { r[1], r[2] }, { r[3], r[4] }, y - SLAB - 1.6, 1.6 + SLAB, 0.6, C(172, 177, 183), M.Metal, false)
		end
		for _, r in ipairs(L.data.rails) do
			if railCut(i, { r[1], r[2] }, { r[3], r[4] }) then
				continue
			end
			local g = panel(atrium, { r[1], r[2] }, { r[3], r[4] }, y, 3.6, 0.25, GLASS, M.Glass)
			if g then
				g.Transparency = 0.55
				g.CastShadow = false
				g.Name = "Balustrade"
			end
			panel(atrium, { r[1], r[2] }, { r[3], r[4] }, y + 3.6, 0.3, 0.45, STEEL, M.Metal)
			local ok, err = pcall(Galleria.balcony, atrium, gctx, i, r, y, SLAB)
			if not ok then
				warn("[EatonCentre] balcony: " .. tostring(err))
			end
		end
	end

	-- The courts' ring inlays on Level 1, and the anchor fronts by the
	-- Yonge & Dundas entrance.
	do
		local ok, err = pcall(function()
			local otherCourts = {}
			for _, m in ipairs(SHARED.medallions or {}) do
				if not overlapsFountain(m[1], m[2], m[3]) then
					table.insert(otherCourts, m)
				end
			end
			Galleria.medallions(levels[1].folder, gctx, otherCourts, levelY(1))
			Galleria.anchorFronts(mall, { P = P, S = S, levelY = levelY, levelData = LEVEL_DATA, tenants = TENANTS, header = HEADER })
		end)
		if not ok then
			warn("[EatonCentre] galleria: " .. tostring(err))
		end
	end

	---------------------------------------------------------------------------
	-- Escalators: each bank is a pair, one running up and one down. The steps are
	-- a sloped plate whose velocity carries you (a conveyor), with a steel truss,
	-- glass balustrades and black handrails; comb plates and landings at the ends.
	---------------------------------------------------------------------------
	local vertical = folderIn(mall, "Vertical_Connections")
	local escFolder = folderIn(vertical, "Escalators")
	local RUBBER = C(24, 24, 26)
	for _, plan in ipairs(escPlans) do
		local bank = plan.bank
		local yb, yt = levelY(bank.from), levelY(bank.to)
		local pb = P(plan.bottom[1], plan.bottom[2], yb)
		local pt = P(plan.top[1], plan.top[2], yt)
		local flat = V3(pt.X - pb.X, 0, pt.Z - pb.Z)
		local across = V3(-flat.Unit.Z, 0, flat.Unit.X)
		for _, side in ipairs({ -1, 1 }) do
			local off = across * side * (ESC_W / 2 + 0.75)
			local a, b = pb + off, pt + off
			local slope = b - a
			local length = slope.Magnitude
			local cf = CFrame.lookAt((a + b) / 2, b)
			-- Steps (the moving surface): top face on the line from floor to floor.
			local steps = Util.solid(escFolder, V3(ESC_W, 0.6, length), cf * CFrame.new(0, -0.3, 0), C(58, 60, 66), M.DiamondPlate)
			steps.Name = side < 0 and "EscalatorUp" or "EscalatorDown"
			local dir = side < 0 and 1 or -1
			steps.AssemblyLinearVelocity = slope.Unit * ESC_SPEED * dir
			steps:SetAttribute("Escalator", side < 0 and "up" or "down")
			-- Truss under the steps.
			Util.deco(escFolder, V3(ESC_W + 0.6, 3, length), cf * CFrame.new(0, -2.1, 0), C(186, 188, 192), M.Metal)
			-- Balustrades and handrails.
			for _, edge in ipairs({ -1, 1 }) do
				local g = Util.solid(escFolder, V3(0.25, 3, length), cf * CFrame.new(edge * (ESC_W / 2 + 0.15), 1.5, 0), GLASS, M.Glass)
				g.Transparency = 0.5
				g.CastShadow = false
				Util.deco(escFolder, V3(0.45, 0.35, length + 0.6), cf * CFrame.new(edge * (ESC_W / 2 + 0.15), 3.1, 0), RUBBER, M.Rubber)
			end
			-- Comb plates where you step on and off.
			for _, info in ipairs({ { a, -slope.Unit }, { b, slope.Unit } }) do
				local pos = info[1]
				local out = V3(info[2].X, 0, info[2].Z).Unit
				local comb = Util.solid(escFolder, V3(ESC_W + 0.6, 0.3, 3), CFrame.lookAt(pos + out * 1.5 + V3(0, -0.1, 0), pos + out * 3 + V3(0, -0.1, 0)), C(150, 152, 158), M.DiamondPlate)
				comb.Name = "CombPlate"
			end
		end
		-- Landings to the floors when an end sits over an opening.
		local pairW = (ESC_W + 1.5) * 2
		for _, info in ipairs({ { pt, plan.dTop, 1, yt }, { pb, plan.dBottom, -1, yb } }) do
			local pos, dist, sgn, y = info[1], info[2], info[3], info[4]
			if dist and dist > 0 then
				local out = flat.Unit * sgn
				local len = dist * S + 4
				local centre = V3(pos.X, y - SLAB / 2, pos.Z) + out * (1.5 + len / 2)
				local landingCF = CFrame.lookAt(centre, centre + out)
				local landing = Util.solid(escFolder, V3(pairW, SLAB, len), landingCF, FLOOR, M.Marble)
				landing.Name = "Landing"
				for _, edge in ipairs({ -1, 1 }) do
					local g = Util.solid(escFolder, V3(0.25, 3.6, len), landingCF * CFrame.new(edge * pairW / 2, SLAB / 2 + 1.8, 0), GLASS, M.Glass)
					g.Transparency = 0.55
					g.CastShadow = false
				end
			end
		end
	end

	-- Stairs beside the added escalators: solid steps, stone treads with a
	-- dark nosing, glass balustrades with a steel handrail either side.
	for _, sp in ipairs(Stores.MALL_STAIRS) do
		local yb, yt = levelY(sp.from), levelY(sp.to)
		local pb, pt = P(sp.bottom[1], sp.bottom[2], yb), P(sp.top[1], sp.top[2], yt)
		local flat = V3(pt.X - pb.X, 0, pt.Z - pb.Z)
		local run, rise = flat.Magnitude, yt - yb
		local dir = flat.Unit
		local n = math.ceil(rise / 0.7)
		local tread, riser = run / n, rise / n
		local W = sp.width * S
		local stairCF = CFrame.lookAt(pb, pb + dir) -- -Z up the stairs
		for k = 1, n do
			local h = k * riser
			local cf = stairCF * CFrame.new(0, h / 2, -(k - 0.5) * tread)
			Util.solid(escFolder, V3(W, h, tread + 0.02), cf, C(206, 200, 190), M.Limestone).Name = "Step"
			Util.deco(escFolder, V3(W, 0.06, 0.25), stairCF * CFrame.new(0, h + 0.02, -(k - 1) * tread - 0.13), C(70, 72, 78), M.Metal)
		end
		local slope = (pt - pb)
		local mid = (pb + pt) / 2
		local scf = CFrame.lookAt(mid, pt)
		for _, edge in ipairs({ -1, 1 }) do
			local g = Util.solid(escFolder, V3(0.25, 3.4, slope.Magnitude), scf * CFrame.new(edge * (W / 2 + 0.15), 1.9, 0), GLASS, M.Glass)
			g.Transparency = 0.55
			g.CastShadow = false
			Util.deco(escFolder, V3(0.3, 0.3, slope.Magnitude + 0.5), scf * CFrame.new(edge * (W / 2 + 0.15), 3.65, 0), STEEL, M.Metal)
			Util.deco(escFolder, V3(0.5, 1.6, slope.Magnitude), scf * CFrame.new(edge * (W / 2 + 0.3), -0.6, 0), C(186, 188, 192), M.Metal)
		end
	end

	---------------------------------------------------------------------------
	-- Columns (public spaces), floor to roof, with a soft light on each level.
	---------------------------------------------------------------------------
	local structure = folderIn(mall, "Structure")
	for k, c in ipairs(SHARED.columns) do
		local p = P(c[1], c[2], 0)
		local foot = onSlab(0, c[1], c[2]) and CONCOURSE_Y or levelY(1)
		local height = (onSlab(4, c[1], c[2]) and roof4Y or roofY) - foot
		Util.cylinder(structure, height, 2.6, CFrame.new(p.X, foot + height / 2, p.Z), C(216, 213, 208), M.SmoothPlastic, true)
		-- every third column wears a coloured ad sleeve at eye level on each
		-- floor, with chrome rings (colour down in the walkways)
		if k % 3 == 0 then
			local SLEEVES = { C(214, 86, 70), C(30, 138, 148), C(228, 178, 60), C(52, 92, 184), C(214, 116, 156), C(96, 150, 84) }
			for i = 1, 3 do
				local fy = levelY(i)
				if fy >= foot - 0.5 and fy + 9 <= foot + height then
					local colour = SLEEVES[(k + i) % #SLEEVES + 1]
					Util.cylinder(structure, 7, 2.85, CFrame.new(p.X, fy + 4.5, p.Z), colour, M.SmoothPlastic, false).CastShadow = false
					for _, yy in ipairs({ fy + 1, fy + 8 }) do
						Util.cylinder(structure, 0.2, 2.95, CFrame.new(p.X, yy, p.Z), C(200, 202, 206), M.Metal, false).CastShadow = false
					end
				end
			end
		end
		if k % 2 == 0 then
			for i = (foot == CONCOURSE_Y) and 0 or 1, 3 do
				local holder = Util.deco(structure, V3(0.2, 0.2, 0.2), CFrame.new(p.X, levelY(i + 1) - 3, p.Z), C(255, 255, 255), M.Neon)
				holder.Transparency = 1
				local light = Instance.new("PointLight")
				light.Range = 22
				light.Brightness = 0.45
				light.Color = C(255, 240, 220)
				light.Shadows = false
				light.Parent = holder
			end
		end
	end

	---------------------------------------------------------------------------
	-- Roof: solid over the shops, flat glass over openings, and the galleria's
	-- glass barrel vault along the skylight traced on the roof plan.
	---------------------------------------------------------------------------
	local roofFolder = folderIn(mall, "Roof")
	for _, r in ipairs(SHARED.roof) do
		plate(roofFolder, r, roofY + SLAB, SLAB, C(80, 84, 90), M.Concrete)
	end
	for _, r in ipairs(SHARED.skylights) do
		local g = plate(roofFolder, r, roofY + 0.4, 0.3, GLASS, M.Glass)
		g.Transparency = 0.5
		g.CastShadow = false
	end
	local capFolder = folderIn(mall, "StreetCaps")
	for _, r in ipairs(SHARED.caps or {}) do
		local c = plate(capFolder, r, base, SLAB, C(196, 194, 188), M.Concrete)
		c.Name = "Pavement"
	end
	for _, r in ipairs(SHARED.roof4 or {}) do
		plate(roofFolder, r, roof4Y + SLAB, SLAB, C(80, 84, 90), M.Concrete)
	end
	for _, r in ipairs(SHARED.skylights4 or {}) do
		local g = plate(roofFolder, r, roof4Y + 0.4, 0.3, GLASS, M.Glass)
		g.Transparency = 0.5
		g.CastShadow = false
	end
	-- The vault: where the skylight runs straight, consecutive strips with the
	-- same span merge into barrel-vault bays (one constant rise, like the real
	-- galleria); where it runs diagonally (the Dundas end), flat framed glass.
	local strips = SHARED.vault
	local function centreOf(st)
		return (st[3] + st[4]) / 2
	end
	local bays, flats = {}, {}
	for k, st in ipairs(strips) do
		local prev, nxt = strips[k - 1], strips[k + 1]
		local shifting = (prev and math.abs(prev[2] - st[1]) < 0.5 and math.abs(centreOf(prev) - centreOf(st)) > 2)
			or (nxt and math.abs(st[2] - nxt[1]) < 0.5 and math.abs(centreOf(nxt) - centreOf(st)) > 2)
		if shifting then
			table.insert(flats, st)
		else
			local last = bays[#bays]
			if last and (last[5] or 0) == (st[5] or 0) and math.abs(last[2] - st[1]) < 0.5 and math.abs(last[3] - st[3]) <= 3 and math.abs(last[4] - st[4]) <= 3 then
				last[2] = st[2]
				last[3] = math.min(last[3], st[3])
				last[4] = math.max(last[4], st[4])
			else
				table.insert(bays, { st[1], st[2], st[3], st[4], st[5] or 0 })
			end
		end
	end
	-- As in the real galleria: the vault springs from a clerestory storey (white
	-- walls with a row of office windows) above Level 3, and is a tall, near
	-- semicircular arch of small panes on white cross ribs.
	local vault = folderIn(mall, "Galleria_Vault")
	local PANES = 16
	local CLER = roof4Y - roofY -- clerestory: up to Level 4's roof line
	local RIB_EVERY = 10 -- studs between cross ribs
	local RIB = C(222, 224, 226) -- vault ribs: pale steel grey, not pure white
	local springY = roofY + CLER
	local officeRng = Random.new(1977)
	local function clerestory(a, b, inward)
		-- A white wall along plan segment a->b on the roof, with a window band.
		local w = panel(vault, a, b, roofY, CLER, 0.8, RIB, M.SmoothPlastic)
		if not w then
			return
		end
		w.Name = "Clerestory"
		-- Office glazing, as in the photos: white piers and floor bands, dark glass.
		Galleria.officeFacade(vault, w, inward, officeRng)
	end
	for _, bay in ipairs(bays) do
		local u0, u1, v0, v1 = bay[1], bay[2], bay[3], bay[4]
		local span = (v1 - v0) * S
		local radius = span / 2
		local rise = math.min(radius * 0.8, 30)
		local length = (u1 - u0) * S
		local centre = P((u0 + u1) / 2, (v0 + v1) / 2, springY)
		local function arc(a, z)
			return V3(centre.X + radius * math.cos(a), springY + rise * math.sin(a), z or centre.Z)
		end
		for n = 0, PANES - 1 do
			local a0, a1 = n / PANES * math.pi, (n + 1) / PANES * math.pi
			local p0, p1 = arc(a0), arc(a1)
			local mid = (p0 + p1) / 2
			local chord = (p1 - p0).Magnitude + 0.2
			local tilt = math.atan2(p1.Y - p0.Y, p1.X - p0.X)
			local pane = Util.solid(vault, V3(chord, 0.25, length), CFrame.new(mid) * CFrame.Angles(0, 0, tilt), GLASS, M.Glass)
			pane.Transparency = 0.45
			pane.CastShadow = false
			-- Purlins along the vault at every pane joint.
			Util.deco(vault, V3(0.35, 0.35, length), CFrame.new(p0 + V3(0, -0.2, 0)), RIB, M.Metal)
		end
		local nRibs = math.max(1, math.floor(length / RIB_EVERY))
		for r = 0, nRibs do
			local z = centre.Z - length / 2 + r * length / nRibs
			for n = 0, PANES - 1 do
				Util.beam(vault, arc(n / PANES * math.pi, z) + V3(0, -0.25, 0), arc((n + 1) / PANES * math.pi, z) + V3(0, -0.25, 0), 0.6, RIB, M.Metal)
			end
		end
		for _, side in ipairs({ -1, 1 }) do
			Util.solid(vault, V3(1.4, 1.2, length), CFrame.new(centre.X + side * radius, springY + 0.6, centre.Z), RIB, M.Metal)
		end
		-- Long fabric banners hanging down the middle of the bay.
		-- (a fuller set of colours, closer together: the mall reads less clinical)
		local BANNERS = { C(214, 86, 70), C(30, 138, 148), C(228, 178, 60), C(186, 40, 56), C(52, 92, 184), C(214, 116, 156) }
		local nB = math.floor(length / 26)
		for k = 1, nB do
			local z = centre.Z - length / 2 + k * length / (nB + 1)
			local b = Util.deco(vault, V3(0.15, 14, 3.5), CFrame.new(centre.X, springY - 6, z), BANNERS[(k % #BANNERS) + 1], M.Fabric)
			b.CastShadow = false
			Util.deco(vault, V3(0.3, 0.3, 4), CFrame.new(centre.X, springY + 1.2, z), RIB, M.Metal)
			Util.deco(vault, V3(0.05, 7, 0.05), CFrame.new(centre.X, springY - 2.4, z), STEEL, M.Metal)
		end
		-- Clerestory walls along both sides (v0 is the east side: larger X), where
		-- Level 4 doesn't run alongside; a white band closes each end of the bay.
		local baseY = (bay[5] == 1) and roof4Y - 2 or roofY
		if bay[5] ~= 1 then
			clerestory({ u0, v0 }, { u1, v0 }, -1)
			clerestory({ u0, v1 }, { u1, v1 }, 1)
		end
		for _, ue in ipairs({ u0, u1 }) do
			panel(vault, { ue, v0 }, { ue, v1 }, baseY, springY + 1.2 - baseY, 0.8, RIB, M.SmoothPlastic)
		end
	end
	for _, st in ipairs(flats) do
		local g = plate(vault, { st[1], st[3], st[2], st[4] }, springY + 1.2, 0.3, GLASS, M.Glass)
		g.Transparency = 0.4
		g.CastShadow = false
		plate(vault, { st[1], st[3], st[1] + 0.8, st[4] }, springY + 1.6, 0.8, RIB, M.Metal)
		if (st[5] or 0) ~= 1 then
			clerestory({ st[1], st[3] }, { st[2], st[3] }, -1)
			clerestory({ st[1], st[4] }, { st[2], st[4] }, 1)
		end
	end

	---------------------------------------------------------------------------
	-- The Yonge & Dundas corner (Exterior.lua): the drum, the anchor's block,
	-- the office tower, the white block on Yonge, and the TMU entrance well.
	---------------------------------------------------------------------------
	do
		Exterior.buildWell(vertical, P, levelY, (TorontoLayout.EATON_LINK and TorontoLayout.EATON_LINK.station) or "DUNDAS")
		-- The fashion anchor on Dundas (unit B212), the one with the red square logo
		-- on Yonge (C301B); a made-up department store's blade sign on Yonge.
		local dundasAnchor = TENANTS["1:B212"] or TENANTS["2:B212"]
		local yongeAnchor = TENANTS["3:C301B"]
		Exterior.build(mall, P, S, base, levelY, Random.new(1977), {
			yonge = yongeAnchor and yongeAnchor.name,
			dundas = dundasAnchor and dundasAnchor.name,
			dept = "Halloran",
		})
		-- Its shop windows, the live window and the sidewalk (Corner.lua).
		local ok, err = pcall(function()
			require(script.Corner).build(mall, P, base, TENANTS["3:B212"] or dundasAnchor, mall:FindFirstChild("YongeDundasCorner", true))
		end)
		if not ok then
			warn("[EatonCentre] corner: " .. tostring(err))
		end
	end

	---------------------------------------------------------------------------
	-- Lifts: glass cabs at every level a shaft serves (from the plans' lift
	-- symbols, grouped across levels). Prompts move you between floors.
	---------------------------------------------------------------------------
	local liftFolder = folderIn(vertical, "Elevators")
	local shafts = {}
	for _, L in ipairs(LEVEL_DATA) do
		local i = L.idx
		for _, lift in ipairs(L.data.lifts) do
			local found
			for _, s in ipairs(shafts) do
				if math.abs(s.u - lift.u) < 6 and math.abs(s.v - lift.v) < 6 then
					found = s
				end
			end
			if not found then
				found = { u = lift.u, v = lift.v, w = lift.w, d = lift.d, stops = {} }
				table.insert(shafts, found)
			end
			found.stops[i] = true
		end
	end
	local tmuLift = Exterior.lift()
	if tmuLift then
		table.insert(shafts, tmuLift)
	end
	local liftCount = 0
	for _, s in ipairs(shafts) do
		local stops = {}
		for i = 0, 4 do
			if s.stops[i] then
				table.insert(stops, i)
			end
		end
		if #stops >= 2 then
			liftCount += 1
			local w = math.max(4, s.w * S)
			local d = math.max(4, s.d * S)
			local cabs = {}
			for _, i in ipairs(stops) do
				local y = levelY(i)
				local p = P(s.u, s.v, y)
				local cab = {}
				-- Floor plate, glass sides, steel roof; open on all sides at floor level.
				Util.solid(liftFolder, V3(w, 0.3, d), CFrame.new(p + V3(0, 0.15, 0)), C(70, 72, 78), M.Metal)
				local roof = Util.solid(liftFolder, V3(w, 0.4, d), CFrame.new(p + V3(0, 9, 0)), C(30, 30, 32), M.Metal)
				Kit.light(roof, Enum.NormalId.Bottom, 12, 1, C(255, 246, 230))
				for _, sx in ipairs({ -1, 1 }) do
					local g = Util.solid(liftFolder, V3(0.2, 8.6, d), CFrame.new(p + V3(sx * w / 2, 4.6, 0)), GLASS, M.Glass)
					g.Transparency = 0.5
				end
				local panelPart = Util.solid(liftFolder, V3(0.6, 3, 1), CFrame.new(p + V3(-w / 2 + 0.6, 3.5, -d / 2 + 0.6)), C(40, 42, 48), M.Metal)
				cab.centre = CFrame.new(p + V3(0, 3, 0))
				cab.panel = panelPart
				cab.level = i
				cabs[i] = cab
			end
			-- The shaft's black steel frame, as on the real glass lifts: corner posts
			-- the full height and a ring of beams at every stop.
			do
				local base0 = P(s.u, s.v, levelY(stops[1]))
				local yTop = levelY(stops[#stops]) + 9.4
				local hgt = yTop - base0.Y
				local BLACK = C(26, 26, 28)
				for _, sx in ipairs({ -1, 1 }) do
					for _, sz in ipairs({ -1, 1 }) do
						Util.deco(liftFolder, V3(0.45, hgt, 0.45), CFrame.new(base0 + V3(sx * (w / 2 + 0.25), hgt / 2, sz * (d / 2 + 0.25))), BLACK, M.Metal)
					end
				end
				for _, i in ipairs(stops) do
					local yy = levelY(i) + 9.4 - base0.Y
					for _, sz in ipairs({ -1, 1 }) do
						Util.deco(liftFolder, V3(w + 0.9, 0.4, 0.3), CFrame.new(base0 + V3(0, yy, sz * (d / 2 + 0.25))), BLACK, M.Metal)
					end
					for _, sx in ipairs({ -1, 1 }) do
						Util.deco(liftFolder, V3(0.3, 0.4, d + 0.9), CFrame.new(base0 + V3(sx * (w / 2 + 0.25), yy, 0)), BLACK, M.Metal)
					end
				end
			end
			for _, i in ipairs(stops) do
				local cab = cabs[i]
				for n, j in ipairs(stops) do
					if j ~= i then
						local target = cabs[j]
						local prompt = Instance.new("ProximityPrompt")
						prompt.ActionText = "Go to " .. ((s.labels and s.labels[j]) or BY_IDX[j].label)
						prompt.ObjectText = "Elevator"
						prompt.KeyboardKeyCode = n == 1 and Enum.KeyCode.E or (n == 2 and Enum.KeyCode.R or Enum.KeyCode.T)
						prompt.HoldDuration = 0.2
						prompt.MaxActivationDistance = 8
						prompt.RequiresLineOfSight = false
						prompt.UIOffset = Vector2.new(0, (n - 1) * 60)
						prompt.Parent = cab.panel
						prompt.Triggered:Connect(function(player)
							local character = player.Character
							local rootPart = character and character:FindFirstChild("HumanoidRootPart")
							if rootPart and (rootPart.Position - cab.centre.Position).Magnitude < 14 then
								character:PivotTo(target.centre * cab.centre:ToObjectSpace(rootPart.CFrame))
							end
						end)
					end
				end
			end
		end
	end

	---------------------------------------------------------------------------
	-- Signs over the main street entrances.
	---------------------------------------------------------------------------
	local signage = folderIn(mall, "Signage")
	local entrances = {}
	for _, w in ipairs(BY_IDX[3].data.walls) do
		if w[5] == 4 and not ((w[1] + w[3]) / 2 > 1336 and (w[2] + w[4]) / 2 < 62) then
			local len = math.sqrt((w[3] - w[1]) ^ 2 + (w[4] - w[2]) ^ 2)
			table.insert(entrances, { w = w, len = len })
		end
	end
	table.sort(entrances, function(a, b)
		return a.len > b.len
	end)
	for k = 1, math.min(6, #entrances) do
		local w = entrances[k].w
		local pa, pb = P(w[1], w[2], 0), P(w[3], w[4], 0)
		local mid = (pa + pb) / 2
		local along = (pb - pa).Unit
		local out = V3(along.Z, 0, -along.X)
		-- Face the street: the side away from the mall centre.
		local centre = P(700, 160, 0)
		if (mid - centre):Dot(out) < 0 then
			out = -out
		end
		local signCF = CFrame.lookAt(mid + out * 1.2 + V3(0, base + 16.5, 0), mid + out * 5 + V3(0, base + 16.5, 0))
		local board = Util.deco(signage, V3(math.min(26, entrances[k].len * S), 3, 0.4), signCF, C(24, 24, 28), M.SmoothPlastic)
		Util.sign(board, Enum.NormalId.Front, "EATON CENTRE", C(255, 255, 255), Enum.Font.GothamBlack).LightInfluence = 0
	end

	---------------------------------------------------------------------------
	-- Wayfinding: one sign family (black plates, white type) for exits, lifts,
	-- washrooms and the subway; a store directory at every escalator landing.
	---------------------------------------------------------------------------
	local function ceilingAbove(i)
		return i == 4 and roof4Y or (i == 3 and roofY or levelY(i + 1) - SLAB)
	end
	-- Exits: inside every street entrance.
	local exitsDone = {}
	for _, w in ipairs(BY_IDX[3].data.walls) do
		if w[5] == 4 then
			local pa, pb = P(w[1], w[2], 0), P(w[3], w[4], 0)
			local mid = (pa + pb) / 2
			if (pb - pa).Magnitude >= 5 then
				local seen = false
				for _, q in ipairs(exitsDone) do
					if (q - mid).Magnitude < 12 then
						seen = true
					end
				end
				if not seen then
					table.insert(exitsDone, mid)
					local along = (pb - pa).Unit
					local inward = V3(along.Z, 0, -along.X)
					if (P(700, 160, 0) - mid):Dot(inward) < 0 then
						inward = -inward
					end
					local at = mid + inward * 2 + V3(0, base + 11, 0)
					Kit.exitSign(signage, CFrame.lookAt(at, at + inward), "EXIT · SORTIE")
				end
			end
		end
	end
	-- Lifts: a sign over each stop.
	for _, s in ipairs(shafts) do
		local count = 0
		for _ in pairs(s.stops) do
			count += 1
		end
		if count >= 2 then
			for i in pairs(s.stops) do
				local p = P(s.u, s.v, levelY(i) + 11)
				Kit.hangingSign(signage, CFrame.new(p), 7, "ELEVATOR", ceilingAbove(i), nil)
			end
		end
	end
	-- Washrooms, where the plans label them.
	for _, L in ipairs(LEVEL_DATA) do
		for _, wr in ipairs(L.data.washrooms or {}) do
			local p = P(wr[1], wr[2], levelY(L.idx) + 11)
			Kit.hangingSign(signage, CFrame.new(p), 9, "WASHROOMS", ceilingAbove(L.idx), nil)
		end
	end
	-- The subway: down to the concourse, and the passage to Dundas station.
	for _, plan in ipairs(escPlans) do
		if plan.bank.from == 0 then
			local top = P(plan.top[1], plan.top[2], levelY(1) + 12)
			local bottom = P(plan.bottom[1], plan.bottom[2], levelY(0) + 11)
			local dir = V3(top.X - bottom.X, 0, top.Z - bottom.Z).Unit
			local s1 = top + dir * 6
			Kit.hangingSign(signage, CFrame.lookAt(s1, s1 + dir), 14, "URBAN EATERY", ceilingAbove(1), C(255, 214, 90))
		end
	end
	if link and link.x then
		local p = V3(link.x, levelY(2) + 11, queenZ - link.u * S + 14)
		Kit.hangingSign(signage, CFrame.lookAt(p, p + V3(0, 0, 1)), 16, "TMU STATION / LINE 1", ceilingAbove(2), C(255, 214, 90))
	end
	-- Directories at the foot and head of every escalator: the level's stores.
	local function directory(i, at, facing)
		local names = {}
		for _, t in pairs(TENANTS) do
			if t.level == i and t.status == "open" and t.name then
				names[t.name] = true
			end
		end
		local list = {}
		for n in pairs(names) do
			table.insert(list, n)
		end
		table.sort(list)
		local board = Util.solid(signage, V3(7, 9, 0.6), CFrame.lookAt(at + V3(0, 5, 0), at + V3(0, 5, 0) + facing), C(30, 32, 38), M.SmoothPlastic)
		board.Name = "Directory"
		for _, face in ipairs({ Enum.NormalId.Front, Enum.NormalId.Back }) do
			local gui = Instance.new("SurfaceGui")
			gui.Face = face
			gui.SizingMode = Enum.SurfaceGuiSizingMode.PixelsPerStud
			gui.PixelsPerStud = 40
			gui.LightInfluence = 0
			local title = Instance.new("TextLabel")
			title.BackgroundColor3 = C(206, 30, 40)
			title.BorderSizePixel = 0
			title.Size = UDim2.new(1, 0, 0, 44)
			title.Font = Enum.Font.GothamBlack
			title.TextScaled = true
			title.TextColor3 = C(255, 255, 255)
			title.Text = "EATON CENTRE · " .. string.upper(BY_IDX[i].label)
			title.Parent = gui
			local cols = 3
			local per = math.ceil(#list / cols)
			for c = 1, cols do
				local col = Instance.new("TextLabel")
				col.BackgroundTransparency = 1
				col.Position = UDim2.new((c - 1) / cols, 6, 0, 52)
				col.Size = UDim2.new(1 / cols, -10, 1, -58)
				col.Font = Enum.Font.Gotham
				col.TextSize = 11
				col.TextXAlignment = Enum.TextXAlignment.Left
				col.TextYAlignment = Enum.TextYAlignment.Top
				col.TextColor3 = C(236, 236, 240)
				col.Text = table.concat(list, string.char(10), (c - 1) * per + 1, math.min(#list, c * per))
				col.Parent = gui
			end
			gui.Parent = board
		end
		Util.solid(signage, V3(1.2, 1, 1.2), CFrame.new(at + V3(0, 0.5, 0)), C(60, 62, 70), M.Metal)
		return board
	end
	for _, plan in ipairs(escPlans) do
		local bottom = P(plan.bottom[1], plan.bottom[2], levelY(plan.bank.from))
		local top = P(plan.top[1], plan.top[2], levelY(plan.bank.to))
		local dir = V3(top.X - bottom.X, 0, top.Z - bottom.Z).Unit
		local side = V3(-dir.Z, 0, dir.X)
		-- Tucked against the escalator's side (inside its footprint), so they never
		-- stand out in a walkway.
		local tuck = ESC_W + 2.5
		if not plan.store then
			directory(plan.bank.from, bottom + dir * 4 + side * tuck, side)
			directory(plan.bank.to, top + dir * 4 + side * tuck, side)
		end
	end

	-- Tell clients where "indoors" is (map tags and the subway pill hide there).
	local zones = Instance.new("StringValue")
	zones.Name = "IndoorZones"
	zones.Value = HttpService:JSONEncode({
		{ minX = rect.minX, maxX = rect.maxX, minZ = rect.minZ, maxZ = rect.maxZ, minY = CONCOURSE_Y - 4, maxY = roof4Y + 40 },
	})
	zones.Parent = ReplicatedStorage

	---------------------------------------------------------------------------
	-- Workplaces move into real units: Grind Coffee (a café counter) and
	-- Metro Threads (a clothing store) on Level 1.
	---------------------------------------------------------------------------
	local units = BY_IDX[1].data.units
	local function frontInfo(u)
		local f = u.front
		if not f then
			return nil
		end
		local len = math.sqrt((f[3] - f[1]) ^ 2 + (f[4] - f[2]) ^ 2)
		return f, len
	end
	local workFolder = folderIn(levels[1].folder, "Interactive_Objects")
	local placed = {}
	-- Metro Threads: a front along the corridor (constant v), at least 60 ft wide
	-- and 60 ft deep, so the 30 x 30-stud store fits.
	local best
	for _, u in ipairs(units) do
		local f, len = frontInfo(u)
		if f and not u.inferred and math.abs(f[6]) > 0.9 and len * S >= 30 and (u.vmax - u.vmin) * S >= 31 then
			if not best or (u.area or 0) > (best.area or 0) then
				best = u
			end
		end
	end
	if best then
		local f = best.front
		local vf = (f[2] + f[4]) / 2
		local um = (f[1] + f[3]) / 2
		-- Outside is toward +v (normal +v) or -v; the store runs the other way.
		local inward = f[6] > 0 and 1 or -1 -- outside at larger v = smaller x, so go +x
		local xFront = yongeX - vf * S
		local zc = queenZ - um * S
		local ok, err = pcall(Workplaces.clothing, workFolder, levelY(1), xFront, inward, zc - 15, zc + 15, "THREADS_EATON", "threads")
		if not ok then
			warn("[EatonCentre] Metro Threads failed: " .. tostring(err))
		else
			placed.threads = best.unit
		end
	end
	-- Grind Coffee: a unit at least 34 ft across its front and 24 ft deep.
	local cafe
	for _, u in ipairs(units) do
		local f, len = frontInfo(u)
		if f and not u.inferred and u.unit ~= placed.threads and len * S >= 17 and math.min(u.umax - u.umin, u.vmax - u.vmin) * S >= 12 and (u.area or 0) > 0 and u.area < 4000 then
			local coffee = (u.name or ""):upper():find("COFFEE") ~= nil
			if not cafe or (coffee and not cafe.coffee) or (coffee == cafe.coffee and (u.area or 0) < (cafe.u.area or 0)) then
				cafe = { u = u, coffee = coffee }
			end
		end
	end
	if cafe then
		local f = cafe.u.front
		local mu, mv = (f[1] + f[3]) / 2, (f[2] + f[4]) / 2
		local front = P(mu, mv, levelY(1))
		local outward = P(mu + f[5], mv + f[6], levelY(1)) - front
		outward = V3(outward.X, 0, outward.Z).Unit
		local back = front - outward * 11.5
		local ok, err = pcall(Workplaces.cafe, workFolder, CFrame.lookAt(back, back + outward), 16, "GRIND_EATON", "grind")
		if not ok then
			warn("[EatonCentre] Grind Coffee failed: " .. tostring(err))
		else
			placed.grind = cafe.u.unit
		end
	end
	---------------------------------------------------------------------------
	-- Interiors: every open shop fitted out for its category, and the Urban
	-- Eatery's tables and chairs where the concourse plan draws them.
	---------------------------------------------------------------------------
	---------------------------------------------------------------------------
	-- Corridor lighting and furniture (from the walkway areas on the plans):
	-- recessed downlights on a ~22 ft spacing (every third casts light), and
	-- benches with planters where a walkway is at least 21 ft wide.
	---------------------------------------------------------------------------
	local GREEN = { C(70, 120, 60), C(90, 140, 70), C(60, 104, 56) }
	for _, L in ipairs(LEVEL_DATA) do
		local i = L.idx
		local y = levelY(i)
		local ceilingY = (i == 4) and roof4Y or ((i == 3) and roofY or levelY(i + 1) - SLAB)
		local fx = folderIn(levels[i].folder, "Lighting")
		for k, pt in ipairs(L.data.lights or {}) do
			-- none where the floor above has been opened up for an added escalator
			if Stores.inWell(i + 1, pt[1], pt[2], 1) then
				continue
			end
			local p = P(pt[1], pt[2], ceilingY - 0.15)
			local disc = Util.cylinder(fx, 0.15, 1.6, CFrame.new(p), C(226, 218, 204), M.Neon, false)
			disc.CastShadow = false
			if k % 3 == 0 then
				local light = Instance.new("PointLight")
				light.Range = 26
				light.Brightness = 0.5
				light.Color = C(255, 244, 226)
				light.Shadows = false
				light.Parent = disc
			end
		end
		local ff = folderIn(levels[i].folder, "Furniture")
		local rngF = Random.new(i * 13 + 5)
		for _, pt in ipairs(L.data.benches or {}) do
			if Stores.inWell(i, pt[1], pt[2], 6) or Stores.inWell(i + 1, pt[1], pt[2], 2) then
				continue -- in or under an added escalator well
			end
			-- Keep the full bench assembly and walking space clear of the seating rim.
			if i == 1 and overlapsFountain(pt[1], pt[2], 11 / S) then
				continue
			end
			local p = P(pt[1], pt[2], y)
			-- A round planter with a small tree, benches either side of it (along the mall).
			Util.cylinder(ff, 2.6, 6, CFrame.new(p + V3(0, 1.3, 0)), C(236, 234, 228), M.SmoothPlastic, true)
			Util.cylinder(ff, 0.2, 5.4, CFrame.new(p + V3(0, 2.65, 0)), C(86, 64, 44), M.Ground, false)
			Util.deco(ff, V3(0.5, 5, 0.5), CFrame.new(p + V3(0, 5, 0)), C(96, 70, 48), M.Wood)
			local crown = Util.deco(ff, V3(5, 4, 5), CFrame.new(p + V3(0, 8.8, 0)), GREEN[rngF:NextInteger(1, #GREEN)], M.LeafyGrass, Enum.PartType.Ball)
			crown.CastShadow = false
			for _, side in ipairs({ -1, 1 }) do
				local bp = p + V3(0, 0, side * 6.5)
				Util.solid(ff, V3(6, 0.5, 1.8), CFrame.new(bp + V3(0, 1.6, 0)), C(170, 130, 92), M.Wood)
				Util.solid(ff, V3(6, 1.35, 1.2), CFrame.new(bp + V3(0, 0.68, 0)), C(70, 72, 78), M.Metal)
			end
		end
	end
	-- The shooting fountain in the L1 court. Floor inlays sit below the walking surface tolerance.
	do
		local p = P(FOUNTAIN_U, FOUNTAIN_V, levelY(1))
		local ff = folderIn(levels[1].folder, "ShootingFountain")
		local function disk(name, diameter, height, bottom, colour, material, solid)
			local part = Util.cylinder(ff, height, diameter * S, CFrame.new(p + V3(0, bottom + height / 2, 0)), colour, material, solid)
			part.Name = name
			return part
		end
		local stone = C(58, 62, 62)
		disk("OuterInlay", COURT_RADIUS * 2, 0.03, 0, stone, M.Marble, false)
		disk("PaleInlay", 24, 0.03, 0.035, C(222, 216, 202), M.Marble, false)
		disk("SeatingPlinth", 20, 1.45, 0, stone, M.Granite, true)
		disk("PoolRim", 16.5, 0.7, 1.45, stone, M.Granite, true)
		local water = disk("FountainWater", 15, 0.08, 2.15, C(141, 173, 158), M.Glass, false)
		water.Transparency = 0.25
		local nozzle = disk("Nozzle", 1.9, 1, 2.2, C(51, 54, 53), M.Metal, false)
		local outlet = Instance.new("Attachment")
		outlet.Parent = nozzle
		outlet.WorldCFrame = CFrame.new(p + V3(0, 3.2, 0))
		local spray = Instance.new("ParticleEmitter")
		spray.Rate = 60
		spray.Lifetime = NumberRange.new(1, 1.4)
		spray.Speed = NumberRange.new(10, 14)
		spray.SpreadAngle = Vector2.new(12, 12)
		spray.Acceleration = Vector3.new(0, -30, 0)
		spray.Size = NumberSequence.new(0.35, 0.1)
		spray.Color = ColorSequence.new(C(220, 240, 255))
		spray.Transparency = NumberSequence.new(0.3, 1)
		spray.EmissionDirection = Enum.NormalId.Top
		spray.Parent = outlet
	end

	local Interiors = require(script.Interiors)
	local skip = {}
	if placed.threads then
		skip[placed.threads] = true
	end
	if placed.grind then
		skip[placed.grind] = true
	end
	local furnished, fieldFixtures, wallRuns = 0, 0, 0
	for _, L in ipairs(LEVEL_DATA) do
		local f = folderIn(levels[L.idx].folder, "Interiors")
		furnished += Interiors.furnish(f, L.idx, L.data.units, P, S, levelY(L.idx), TENANTS, L.idx == 1 and skip or {}, L.idx * 101 + 7)
		fieldFixtures += Interiors.fill(f, L.idx, L.data.units, P, S, levelY(L.idx), TENANTS, L.idx == 1 and skip or {}, L.idx * 131 + 3)
		wallRuns += Interiors.walls(f, L.idx, L.data.units, P, S, levelY(L.idx), TENANTS, L.idx == 1 and skip or {}, L.idx * 151 + 9)
	end
	local seating = folderIn(levels[0].folder, "FoodCourt_Seating")
	local furniture = {}
	for _, item in ipairs(require(DATA.Furniture)) do
		if not Stores.inWell(1, item.u, item.v, 3) then
			table.insert(furniture, item)
		end
	end
	local seats = Interiors.foodCourt(seating, furniture, P, S, levelY(0))
	-- The Urban Eatery's warm wood-slat ceiling over its seating (photos): the
	-- seating's 12 ft cells, slats running along each row of cells.
	do
		local CELL = 12
		local cells = {}
		for _, item in ipairs(furniture) do
			local cu, cv = math.floor(item.u / CELL), math.floor(item.v / CELL)
			cells[cu] = cells[cu] or {}
			cells[cu][cv] = true
		end
		local slats = folderIn(seating, "SlatCeiling")
		local cy = levelY(1) - SLAB - 1.2
		for cu, row in pairs(cells) do
			local vs = {}
			for cv in pairs(row) do
				table.insert(vs, cv)
			end
			table.sort(vs)
			local i = 1
			while i <= #vs do
				local j = i
				while j < #vs and vs[j + 1] == vs[j] + 1 do
					j += 1
				end
				-- a run of cells from vs[i] to vs[j] in this u row
				local v0, v1 = vs[i] * CELL, (vs[j] + 1) * CELL
				local u0 = cu * CELL
				for k = 0.75, CELL - 0.75, 1.5 do
					local a, b = P(u0 + k, v0, cy), P(u0 + k, v1, cy)
					local mid = (a + b) / 2
					Util.deco(slats, V3(math.abs(b.X - a.X) + 0.1, 0.9, 0.45), CFrame.new(mid), C(196, 146, 96), M.Wood).CastShadow = false
				end
				-- warm downlights through the slats (the concourse is underground)
				if cu % 2 == 0 then
					for cv2 = vs[i], vs[j], 2 do
						local lp = P(u0 + CELL / 2, (cv2 + 0.5) * CELL, cy - 0.6)
						local holder = Util.deco(slats, V3(0.8, 0.2, 0.8), CFrame.new(lp), C(255, 236, 206), M.Neon)
						holder.CastShadow = false
						local l = Instance.new("PointLight")
						l.Range = 24
						l.Brightness = 0.9
						l.Color = C(255, 226, 190)
						l.Shadows = false
						l.Parent = holder
					end
				end
				i = j + 1
			end
		end
	end
	print(string.format("[EatonCentre] interiors: %d shops fitted out, %d floor fixtures, %d wall displays, %d food court pieces", furnished, fieldFixtures, wallRuns, seats))

	print(string.format("[EatonCentre] built from plans: %d lifts, %d vault bays, Metro Threads in %s, Grind Coffee in %s",
		liftCount, #bays, tostring(placed.threads), tostring(placed.grind)))

	CollectionService:AddTag(mall, "EatonCentre")
	return mall
end

return EatonCentre
